    'faq_note' => 'Answers to common questions.',
    'faq_q1' => '<strong>What is TropaTT?</strong><br>A free open-source self-hosted CRM, task manager, and project management platform.',
    'faq_q10' => 'Who is the developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM or a task manager?</strong><br>Both. A CRM for clients and counterparties, a task manager for tasks, plus project management, chat, calendar, and AI.',
    'faq_q3' => '<strong>Is it suitable for freelancers?</strong><br>Yes. There is no minimum team size. A single user gets CRM, tasks, an AI day plan, and chat without per-seat fees.',
    'faq_q4' => '<strong>Does it work on shared hosting?</strong><br>Yes. PHP 8.1+ and MySQL are enough. The browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits on users and tasks?</strong><br>No. Unlimited users, tasks, projects, and clients. The only limitation is server capacity.',
    'faq_q6' => '<strong>Where is the data stored?</strong><br>100% on your server. The system never syncs data to the cloud.',
    'faq_q7' => '<strong>What AI tools are available?</strong><br>20+ tools: idea exploration, day/week plans, summaries, checklists, risks, meeting preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API with an OpenAPI 3.1 spec generated from code.',
    'faq_q9' => '<strong>Can it be customized?</strong><br>Yes. PHP code, modules, webhooks, API, workflow rules, custom fields, roles, and access rights.',
    'faq_title' => 'Frequently asked questions',
