    'usage_cycle_heading' => '完整的客户工作周期',
    'usage_step1' => '<strong>捕获</strong> — 想法、客户请求、问题或传入线索。',
    'usage_step2' => '<strong>分析</strong> — 独立或通过 AI：范围、风险、可行性、方法。',
    'usage_step3' => '<strong>结构化</strong> — 分为项目、任务、子任务、检查清单、负责人、截止日期。',
    'usage_step4' => '<strong>协调</strong> — 通过聊天、评论、@提及、通知。',
    'usage_step5' => '<strong>执行</strong> — 任务列表、看板、我的一天、我的一周。',
    'usage_step6' => '<strong>跟踪</strong> — 甘特图、仪表盘、分析、负载、风险信号。',
    'usage_step7' => '<strong>自动化</strong> — 工作流规则、SLA、Webhook、审批链。',
    'usage_examples_heading' => '具体示例',
    'usage_ex1' => '<strong>自由职业者：</strong>客户请求 → AI 分析 → 任务计划 → 我的一天 → 执行 → 客户聊天 → 完成。',
    'usage_ex2' => '<strong>代理商：</strong>客户简报 → AI 分解 → 项目 + 里程碑 → 看板 → 甘特跟踪 → 客户报告 → 分析。',
    'usage_ex3' => '<strong>服务公司：</strong>交易对手 → 项目 → 安装任务 → 甘特 → 每日计划 → SLA 监控 → 签署验收。',
    'usage_ex4' => '<strong>B2B 运营：</strong>公司 → 联系人 → 任务 + 审批 → 提醒 → Webhook → 仪表盘。',
