    'tech_stack_heading' => '技术栈',
    'tech_stack1' => '<strong>后端：</strong>PHP 8.1+，自定义微内核。零外部依赖。无 Laravel/Symfony/Doctrine。',
    'tech_stack2' => '<strong>数据库：</strong>MySQL。',
    'tech_stack3' => '<strong>前端：</strong>PHP 渲染 MPA + Bootstrap 5 + 自定义 vanilla JS ES5+ 模块。无 React/Vue/Angular。无构建工具。',
    'tech_stack4' => '<strong>架构：</strong>API 优先。Web UI 使用 REST API 获取所有数据。Web 层零直接数据库调用。',
